function openDraftDatabase(){if(!draftDatabase)draftDatabase=new Promise((resolve,reject)=>{const request=indexedDB.open('paper-studio-drafts',1);request.onupgradeneeded=()=>request.result.createObjectStore('documents');const timeout=setTimeout(()=>reject(Error('浏览器数据库不可用')),2000);request.onsuccess=()=>{clearTimeout(timeout);resolve(request.result);};request.onblocked=()=>{clearTimeout(timeout);reject(Error('数据库被阻止'));};request.onerror=()=>{clearTimeout(timeout);reject(request.error);};});return draftDatabase;}
async function indexedDraft(mode,record,storageKey=DRAFT_KEY){const database=await openDraftDatabase();return new Promise((resolve,reject)=>{let finished=false;const transaction=database.transaction('documents',mode==='get'?'readonly':'readwrite'),store=transaction.objectStore('documents');const request=mode==='get'?store.get(storageKey):store.put(record,storageKey);const timer=setTimeout(()=>{if(finished)return;finished=true;try{transaction.abort();}catch{}reject(Error('浏览器存储读取超时'));},2000);transaction.oncomplete=()=>{if(finished)return;finished=true;clearTimeout(timer);resolve(request.result);};const fail=()=>{if(finished)return;finished=true;clearTimeout(timer);reject(transaction.error||Error('浏览器存储不可用'));};transaction.onerror=fail;transaction.onabort=fail;});}

async function readIndexedDraft(storageKey=DRAFT_KEY){try{const value=await indexedDraft('get',null,storageKey);indexedReadFailed=false;return value?parseDocument(JSON.stringify(value)):null;}catch{indexedReadFailed=true;return null;}}
function backupToIndexed(record){if(indexedReadFailed){$('saveState').textContent='浏览器存储不可用';$('saveState').dataset.state='error';return;}indexedDraft('put',record).then(()=>{$('saveState').textContent='已自动保存';$('saveState').dataset.state='saved';$('saveState').title='已保存到本机浏览器数据库';}).catch(()=>{$('saveState').textContent='浏览器禁止自动保存';$('saveState').dataset.state='error';$('saveState').title='请保存或复制草稿；用完整浏览器打开文件后再试';});}
function documentRecord(){syncChapter();return {book:JSON.parse(JSON.stringify(book)),format:'paper-studio',version:1,editorVersion:3,savedAt:new Date().toISOString(),html:editor.innerHTML,assets:referencedMusicAssets(),images:referencedImageAssets(),settings:{storyFull:$('storyFull').checked,noCSS:$('noCSS').checked,storyTheme:$('storyTheme')?.value||'gray'}};}
function parseDocument(text){const doc=JSON.parse(text);if(!doc||doc.format!=='paper-studio'||doc.version!==1||typeof doc.html!=='string')throw Error('不是纸间的正文保存文件');const settings=doc.settings||{};return {...doc,settings:{sender:typeof settings.sender==='string'?settings.sender:'',recipient:typeof settings.recipient==='string'?settings.recipient:'',storyFull:typeof settings.storyFull==='boolean'?settings.storyFull:true,noCSS:typeof settings.noCSS==='boolean'?settings.noCSS:true,storyTheme:['black','white','gray'].includes(settings.storyTheme)?settings.storyTheme:'gray'}};}
function readStored(key){try{const data=localStorage.getItem(key);return data?parseDocument(data):null;}catch{return null;}}
function persist(){if(!workLibraryReady)return false;const record=workspaceRecord();let prior=null;try{prior=localStorage.getItem(DRAFT_KEY);}catch{}$('count').textContent=editorText(editor).replace(/\s/g,'').length+' 字';try{localStorage.setItem(DRAFT_KEY,JSON.stringify(record));$('saveState').textContent='已自动保存';$('saveState').dataset.state='saved';$('saveState').title='自动保存于 '+new Date(record.savedAt).toLocaleTimeString();}catch{backupToIndexed(record);$('saveState').textContent='正在尝试备用保存';$('saveState').dataset.state='error';$('saveState').title='请点击「保存到本地」，把正文下载为文件。';return false;}if(prior&&Date.now()-lastBackupAt>30000){try{parseDocument(prior);localStorage.setItem(BACKUP_KEY,prior);lastBackupAt=Date.now();}catch{/* Current draft remains saved if the optional backup fails. */}}return true;}
function preserveBackup(){try{localStorage.setItem(BACKUP_KEY,JSON.stringify(workspaceRecord()));lastBackupAt=Date.now();}catch{/* A local document file can still be saved without browser storage. */}}
function sanitizeDocument(markup){const template=document.createElement('template');template.innerHTML=markup;const allowed=new Set(['P','DIV','SPAN','LABEL','BR','B','STRONG','EM','I','U','S','MARK','DETAILS','SUMMARY','BLOCKQUOTE','PRE','CODE','HR','BUTTON','DFN']);const discard=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','LINK','META','BASE','SVG','MATH','TEMPLATE']);for(const el of [...template.content.querySelectorAll('*')]){if(discard.has(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}for(const attr of [...el.attributes])if(!['class','data-editable','data-widget','data-field','data-placeholder','data-action','data-ending','data-node-id','data-next-id','data-sound-url','data-sound-volume','data-board-x','data-board-y','tabindex','aria-label','aria-hidden'].includes(attr.name))el.removeAttribute(attr.name);}return template.innerHTML;}
function applySettings(settings){$('storyFull').checked=settings.storyFull;$('noCSS').checked=settings.noCSS;$('storyTheme').value=settings.storyTheme||'gray';}
