function minitoolRuntime(){
  'use strict';
  Array.from(document.querySelectorAll('.letter-scene .trifold_letter')).forEach(function(letter){
    var toggle=letter.querySelector('.letter-switch'),second=letter.querySelector('.trifold_letter2');
    if(!toggle||!second)return;
    var controls=document.createElement('div');controls.className='minitool-letter-controls';controls.setAttribute('role','group');controls.setAttribute('aria-label','切换信纸');
    var firstButton=document.createElement('button'),secondButton=document.createElement('button');
    firstButton.type='button';secondButton.type='button';firstButton.textContent='第一张';secondButton.textContent='第二张';controls.appendChild(firstButton);controls.appendChild(secondButton);letter.parentNode.insertBefore(controls,letter);
    function selectSheet(useSecond){letter.classList.toggle('is-second',useSecond);firstButton.setAttribute('aria-pressed',String(!useSecond));secondButton.setAttribute('aria-pressed',String(useSecond));}
    firstButton.addEventListener('click',function(event){event.preventDefault();event.stopPropagation();selectSheet(false);});
    secondButton.addEventListener('click',function(event){event.preventDefault();event.stopPropagation();selectSheet(true);});
    second.addEventListener('click',function(event){if(!toggle.open||event.target.closest('summary,button,a,input,audio'))return;event.stopPropagation();selectSheet(true);});
    toggle.addEventListener('toggle',function(){controls.hidden=!toggle.open;if(!toggle.open)selectSheet(false);});
    controls.hidden=!toggle.open;selectSheet(false);
  });

}
