 button.addEventListener('click',function(){epoch++;if(enabled){enabled=false;tracks.forEach(stop);button.textContent='开启页面音效';return;}button.disabled=true;var ready;if(window.PaperPCM)ready=window.PaperPCM.unlock();else ready=Promise.all(tracks.map(function(item){item.audio.muted=true;return Promise.resolve(item.audio.play()).then(function(){item.audio.pause();item.audio.currentTime=0;item.audio.muted=false;},function(error){item.audio.muted=false;throw error;});}));Promise.resolve(ready).then(function(){enabled=true;failed=new WeakSet();button.textContent='关闭页面音效';schedule();},function(){button.textContent='无法开启声音，请再次点击';}).then(function(){button.disabled=false;});});
