/* SMS widgets store all author settings as sanitized, portable editable fields. */
function smsMessage(text='',side='them',time='',read=false,receipt='已读'){
 return '<div class="sms-author-message" data-field="sms-message"><div class="sms-message-meta">'+editField(side,'sms-side','归属（you＝我，them＝对方）')+editField(time,'sms-time','时间')+editField(read?'yes':'no','sms-read','已读（yes / no）')+editField(receipt,'sms-receipt','回执文字')+'</div>'+editBody(paragraphs(text),'sms-text')+'</div>';
}
function sms(text=''){
 const options=[['sms-name','','联系人'],['sms-avatar','','头像 HTTPS（可空）'],['sms-theme','blue','气泡配色（blue / green / gray）'],['sms-radius','18','气泡圆角（12 / 18 / 24）'],['sms-night','no','夜间外观（yes / no）'],['sms-status','yes','状态栏（yes / no）'],['sms-clock','9:41','状态栏时间'],['sms-signal','4','信号格数（0—4）'],['sms-battery','yes','电池（yes / no）'],['sms-percent','82','电量（0—100）'],['sms-header','yes','联系人栏（yes / no）'],['sms-typing','no','正在输入（yes / no）'],['sms-typing-side','them','正在输入归属（you / them）'],['sms-typing-place','end','正在输入位置（start / end）'],['sms-composer','yes','底部输入栏（yes / no）'],['sms-draft','','未发送的字'],['sms-placeholder','iMessage','输入栏占位提示']];
 const messages=text.split(/\n\s*\n/).filter(x=>x.trim());if(!messages.length)messages.push('');
 return editBlock('sms','短信','<div class="sms-author-settings">'+options.map(([key,value,label])=>editField(value,key,label)).join('')+'</div><div class="sms-author-messages" data-field="body">'+messages.map(value=>smsMessage(value)).join('')+'</div>');
}
function renderSMS(source){
 const get=key=>fieldText(source,'sms-'+key),yes=key=>get(key)==='yes',safeChoice=(value,values,fallback)=>values.includes(value)?value:fallback;
 const theme=safeChoice(get('theme'),['blue','green','gray'],'blue'),radius=safeChoice(get('radius'),['12','18','24'],'18');
 const percent=Math.max(0,Math.min(100,Math.round(Number(get('percent'))||0))),signal=Math.max(0,Math.min(4,Math.round(Number(get('signal'))||0))),name=get('name'),avatar=imageLink(get('avatar'));
 if(get('avatar')&&!avatar)throw Error('短信头像请填写 HTTPS 图片直链，或清空后使用姓名首字。');
 const status=yes('status')?'<div class="statusbar"><table class="sb"><tbody><tr><td class="sb-time">'+esc(get('clock'))+'</td><td class="sb-ind"><span class="bars">'+[1,2,3,4].map(i=>'<span class="b'+i+(i<=signal?' on':'')+'"></span>').join('')+'</span>'+(yes('battery')?'<span class="battery"><span class="bat-shell"><span class="bat-fill bat-'+Math.round(percent/10)*10+(percent<=20?' low':'')+'"></span></span><span class="bat-nub"></span><span class="bat-pct">'+percent+'%</span></span>':'')+'</td></tr></tbody></table></div>':'';
 const header=yes('header')?'<div class="conv-header"><table class="ch"><tbody><tr><td class="ch-chev">‹</td><td class="ch-mid"><div class="avatar">'+(avatar?'<img src="'+esc(avatar)+'" alt="'+esc(name?name+'的头像':'联系人头像')+'">':'<span class="initial">'+esc(Array.from(name)[0]||'')+'</span>')+'</div><span class="conv-name">'+esc(name)+'</span></td><td class="ch-info">ⓘ</td></tr></tbody></table></div>':'';
 const typing=yes('typing')?'<div class="message-bubble typing '+(get('typing-side')==='you'?'you':'them')+'" aria-label="正在输入"><span class="dot"></span><span class="dot"></span><span class="dot"></span></div>':'';
 let messages='';for(const message of source.querySelectorAll(':scope > [data-field=body] > [data-field=sms-message]')){const content=message.querySelector('[data-field=sms-text]'),time=fieldText(message,'sms-time'),read=fieldText(message,'sms-read')==='yes'?fieldText(message,'sms-receipt'):'';messages+='<div class="message-bubble '+(fieldText(message,'sms-side')==='you'?'you':'them')+'"><div class="sms-message-copy">'+partsHTML(renderParts(content))+'</div>'+((time||read)?'<span class="meta">'+esc([time,read].filter(Boolean).join(' · '))+'</span>':'')+'</div>';}
 const draft=get('draft'),composer=yes('composer')?'<div class="composer"><div class="input'+(draft?' has':'')+'">'+esc(draft||get('placeholder'))+'</div><div class="send" aria-hidden="true">↑</div></div>':'';
 return '<div class="imessage sms-theme-'+theme+' sms-radius-'+radius+(yes('night')?' sms-night':'')+'">'+status+header+'<div class="screen">'+(get('typing-place')==='start'?typing:'')+messages+(get('typing-place')==='start'?'':typing)+'</div>'+composer+'</div>';
}
function appendSMSFields(fields,source,canvas=null){
 const panel=document.createElement('div');panel.className='sms-editor';fields.append(panel);
 const note=document.createElement('p');note.className='flash-editor-note';note.textContent='短信为剧情排版，输入栏、已读和正在输入仅作外观展示；两种平台均使用静态 HTML / CSS。';panel.append(note);
 function field(key){return source.querySelector('[data-field="sms-'+key+'"]');}
 function save(key,value){const target=field(key);if(!target)return;checkpoint();target.textContent=value;checkpoint();if(canvas)renderSMSCanvas(source,canvas);}
 function control(parent,label,key,kind='text',choices=null){const wrap=document.createElement('label');wrap.className='sms-control';const caption=document.createElement('span');caption.textContent=label;wrap.append(caption);let input;if(choices){input=document.createElement('select');for(const [value,text] of choices){const option=document.createElement('option');option.value=value;option.textContent=text;input.append(option);}}else{input=document.createElement('input');input.type=kind;}input.setAttribute('aria-label',label);if(kind==='checkbox')input.checked=fieldText(source,'sms-'+key)==='yes';else input.value=fieldText(source,'sms-'+key);input.addEventListener('change',()=>{if(kind==='url'&&input.value&&!imageLink(input.value)){input.setCustomValidity('请使用 HTTPS 图片直链');input.reportValidity();return;}input.setCustomValidity('');let value=kind==='checkbox'?(input.checked?'yes':'no'):input.value;if(kind==='number'){value=String(Math.max(0,Math.min(key==='percent'?100:4,Math.round(Number(value)||0))));input.value=value;}save(key,value);});if(kind==='number'){input.min='0';input.max=key==='percent'?'100':'4';}if(kind==='text'&&!choices)input.addEventListener('input',()=>save(key,input.value));wrap.append(input);parent.append(wrap);return input;}
 function section(label,open=false){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=label;details.open=open;details.append(summary);panel.append(details);return details;}
 const basic=section('外观与联系人',true);control(basic,'联系人名称','name');control(basic,'头像 HTTPS 直链（可留空）','avatar','url');control(basic,'气泡配色','theme','text',[['blue','蓝色'],['green','绿色'],['gray','灰色']]);control(basic,'气泡圆角','radius','text',[['12','12'],['18','18'],['24','24']]);control(basic,'夜间模式','night','checkbox');control(basic,'显示联系人栏','header','checkbox');
 const status=section('状态栏');control(status,'显示状态栏','status','checkbox');control(status,'状态栏时间','clock');control(status,'信号格数','signal','number');control(status,'显示电池','battery','checkbox');control(status,'电池百分比','percent','number');
 const title=document.createElement('strong');title.textContent='对话内容';panel.append(title);const list=document.createElement('div');list.className='sms-message-list';panel.append(list);
 function messages(){return [...source.querySelectorAll(':scope > [data-field=body] > [data-field=sms-message]')];}
 function paint(){list.replaceChildren();messages().forEach((message,index)=>{const row=document.createElement('section');row.className='sms-message-editor';const tools=document.createElement('div');tools.className='sms-message-tools';const side=document.createElement('select');side.setAttribute('aria-label','第 '+(index+1)+' 条消息归属');for(const [value,label] of [['them','对方'],['you','我']]){const o=document.createElement('option');o.value=value;o.textContent=label;side.append(o);}side.value=fieldText(message,'sms-side');side.onchange=()=>{checkpoint();message.querySelector('[data-field=sms-side]').textContent=side.value;checkpoint();if(canvas)renderSMSCanvas(source,canvas);};tools.append(side);
 function action(label,callback,disabled=false){const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;b.onclick=()=>{checkpoint();callback();checkpoint();paint();};tools.append(b);}
 action('上移',()=>message.previousElementSibling.before(message),index===0);action('下移',()=>message.nextElementSibling.after(message),index===messages().length-1);action('删除',()=>message.remove());row.append(tools);
 if(!canvas){ const text=paperSurface(message.querySelector('[data-field=sms-text]'),0,'sms-text-paper');text.setAttribute('aria-label','第 '+(index+1)+' 条短信正文');text.dataset.placeholder='输入这条短信…';text.addEventListener('input',()=>{message.querySelector('[data-field=sms-text]').innerHTML=sanitizeDocument(text.innerHTML);checkpoint();});row.append(text);}

 function meta(label,key,type='text'){const wrap=document.createElement('label');wrap.className='sms-control';const c=document.createElement('span');c.textContent=label;const input=document.createElement('input');input.type=type;input.setAttribute('aria-label','第 '+(index+1)+' 条'+label);if(type==='checkbox')input.checked=fieldText(message,key)==='yes';else input.value=fieldText(message,key);input.onchange=()=>{checkpoint();message.querySelector('[data-field="'+key+'"]').textContent=type==='checkbox'?(input.checked?'yes':'no'):input.value;checkpoint();if(canvas)renderSMSCanvas(source,canvas);};if(type==='text')input.addEventListener('input',()=>{message.querySelector('[data-field="'+key+'"]').textContent=input.value;checkpoint();if(canvas)renderSMSCanvas(source,canvas);});wrap.append(c,input);row.append(wrap);}
 meta('时间','sms-time');meta('显示已读','sms-read','checkbox');meta('回执文字','sms-receipt');list.append(row);});if(canvas)renderSMSCanvas(source,canvas);}
 paint();const add=document.createElement('button');add.type='button';add.className='sms-add-message';add.textContent='＋ 添加一条消息';add.onclick=()=>{checkpoint();source.querySelector(':scope > [data-field=body]').insertAdjacentHTML('beforeend',smsMessage());checkpoint();paint();list.lastElementChild?.scrollIntoView({block:'nearest'});};panel.append(add);
 const extra=section('正在输入与底部输入栏');control(extra,'显示正在输入','typing','checkbox');control(extra,'正在输入归属','typing-side','text',[['them','对方'],['you','我']]);control(extra,'正在输入位置','typing-place','text',[['end','对话末尾'],['start','对话开头']]);control(extra,'显示底部输入栏','composer','checkbox');control(extra,'未发送的文字','draft');control(extra,'输入栏占位提示','placeholder');
}

