 const item=graphNodes.get(graphSelection);if(item)item.text=editorText(inspectorSource);const source=inspectorSource;if(source.dataset.widget==='polaroid'){const host=item?.card?.querySelector('.polaroid-edit-photo');if(host)renderPolaroidEditPhoto(source,host);}clearTimeout(inspectorPreviewTimer);inspectorPreviewTimer=setTimeout(()=>{const current=[...graphNodes.values()].find(node=>node.source===source),host=current?.card?.querySelector('.graph-appearance');if(!source.isConnected||!host||host.hidden)return;const frame=graphThumb(current);if(frame)host.replaceChildren(frame);},250);
